academic.css:
/* Archetype A3, academic long form: a narrow date gutter and one reading flow, built to run to
   several pages (publications, grants, teaching via custom sections). Each row is gutter then
   body in DOM order, so an ATS reads "date, title, place". No letter-spacing and no uppercase
   transform. The renderer adds the page rule and font faces from the manifest and overrides
   the :root tokens. */
:root {
  --accent: #6b1d1d; --ink: #1c1c1c; --muted: #555555; --hair: #c9c2bd;
  --font-head: "Source Serif 4"; --font-body: "Source Serif 4"; --scale: 1;
  --gutter: 18%; --gap: 5mm;
}
* { box-sizing: border-box; }
body {
  margin: 0; color: var(--ink);
  font: calc(10pt * var(--scale)) / 1.4 var(--font-body), Georgia, "Times New Roman", serif;
}
h1, h2, h3 { font-family: var(--font-head), Georgia, "Times New Roman", serif; }
p, ul, ol { margin: 0; }
a { color: inherit; text-decoration: none; }

.head { margin-bottom: 14pt; text-align: center; }
h1 { margin: 0; font-size: 2.3em; line-height: 1.1; font-weight: 700; }
.headline { margin-top: 2pt; font-size: 1.1em; font-style: italic; color: var(--muted); }
.contact { margin: 4pt 0 0; padding: 0; list-style: none; color: var(--muted); }
.contact li { display: inline; }
.contact li + li::before { content: " | "; }

h2 { break-after: avoid; margin: 0 0 6pt; padding-bottom: 1.5pt; color: var(--accent); font-size: 1.2em; font-weight: 700; border-bottom: 0.6pt solid var(--hair); }
.sec { margin-bottom: 13pt; }
.row { display: grid; grid-template-columns: var(--gutter) 1fr; column-gap: var(--gap); }
.entry { break-inside: avoid; margin-bottom: 6pt; }
.gutter { color: var(--muted); }
h3 { margin: 0; font-size: 1em; font-weight: 700; }
.org { font-style: italic; }
.body p + p, .body p + ul { margin-top: 2pt; }
.body ul { padding-left: 12pt; }
.body li { margin-top: 1pt; }
.pubs { margin: 0; padding-left: 18pt; }
.pubs li { break-inside: avoid; margin-bottom: 4pt; }
.item:not(:last-of-type)::after { content: ","; }

