rirekisho.css:
/* Archetype A8, the Japanese rirekisho: a ruled form. Personal data beside the ID photo box,
   then one grid per section, each row a date cell then the entry, read left to right in DOM
   order. Latin text uses the bundled serif; no CJK font is bundled, so Japanese falls back to
   the system's Mincho / Noto CJK (tofu on a machine with none). No letter-spacing. */
:root {
  --ink: #1a1a1a; --rule: #1a1a1a; --muted: #555;
  --font-body: "Source Serif 4"; --scale: 1;
}
* { box-sizing: border-box; }
body {
  margin: 0; color: var(--ink);
  font: calc(9.5pt * var(--scale)) / 1.4 var(--font-body), "Yu Mincho", "YuMincho", "Hiragino Mincho ProN", "Noto Serif CJK JP", "Noto Serif JP", "MS Mincho", serif;
}
p, ul { margin: 0; }
a { color: inherit; text-decoration: none; }

.top { display: flex; align-items: flex-start; gap: 5mm; margin-bottom: 6mm; }
.id { flex: 1; }
.titlebar { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 2mm; }
.doc { font-size: 1.9em; font-weight: 600; }
.asof { color: var(--muted); }
h1 { margin: 0; font-size: 1.7em; line-height: 1.2; font-weight: 600; }
.photo { flex: none; width: 30mm; height: 40mm; margin-top: 6mm; border: 0.6pt dashed var(--rule); }
.photo img { display: block; width: 100%; height: 100%; object-fit: cover; }

.grid { width: 100%; border-collapse: collapse; margin-bottom: 4mm; }
.grid th, .grid td { padding: 2pt 4pt; border: 0.6pt solid var(--rule); text-align: left; vertical-align: top; font-weight: 400; }
.grid tr { break-inside: avoid; }
.grid th { width: 32mm; color: var(--muted); }
.grid .head th { text-align: center; color: var(--ink); font-weight: 600; }
.grid .head th + th { width: auto; }
.grid .box td { height: 22mm; }
.sub { color: var(--muted); }
.item:not(:last-of-type)::after { content: ","; }
.cefr b { font-weight: 600; margin-right: 6pt; }

