.entry li { margin-top: 1.5pt; }

.side h3 { font-size: 1.05em; }
.tags { margin-top: 3pt; }
.tag { display: inline-block; margin: 0 6pt 4pt 0; padding-bottom: 1pt; border-bottom: 1pt solid var(--hair); }
.lang { display: flex; justify-content: space-between; padding: 2pt 0; border-bottom: 0.75pt dashed var(--hair); }
.lang:last-child { border-bottom: 0; }
.lang-name { font-weight: 700; }
