us-resume.css:
/* Archetype A1, US résumé: Letter, one page, no photo and no personal details (date of birth,
   nationality) - US hiring practice leaves them off. Dense single column, ruled headings, dates
   right-aligned; the DOM order is the reading order. No letter-spacing and no uppercase
   transform. The renderer adds the page rule and font faces from the manifest and overrides
   the :root tokens. */
:root {
  --accent: #111111; --ink: #111111; --muted: #444444;
  --font-head: "Inter"; --font-body: "Inter"; --scale: 1;
}
* { box-sizing: border-box; }
body {
  margin: 0; color: var(--ink);
  font: calc(9.2pt * var(--scale)) / 1.32 var(--font-body), Arial, Helvetica, sans-serif;
}
h1, h2, h3 { font-family: var(--font-head), Arial, Helvetica, sans-serif; }
p, ul { margin: 0; }
a { color: inherit; text-decoration: none; }

.head { text-align: center; margin-bottom: 6pt; }
h1 { margin: 0; font-size: 2.1em; line-height: 1.1; font-weight: 700; }
.contact { margin: 3pt 0 0; padding: 0; list-style: none; color: var(--muted); }
.contact li { display: inline; }
.contact li + li::before { content: " | "; }

h2 { break-after: avoid; margin: 0 0 3pt; padding-bottom: 1pt; color: var(--accent); font-size: 1.1em; font-weight: 700; border-bottom: 0.8pt solid var(--accent); }
.sec { margin-bottom: 7pt; }
.entry { break-inside: avoid; margin-bottom: 4pt; }
.row { display: flex; justify-content: space-between; align-items: baseline; gap: 8pt; }
h3 { margin: 0; font-size: 1em; font-weight: 700; }
.when { flex: none; }
.sub { font-style: italic; }
.entry p { margin-top: 1pt; }
.entry ul { margin-top: 1pt; padding-left: 12pt; }
.entry li { margin-top: 0.5pt; }
.line + .line { margin-top: 1pt; }
.item:not(:last-of-type)::after { content: ","; }
